// AsyncIterator consumer
const conduit = client.streamConduit({ prompt });
for await (const chunk of conduit) { renderChunk(chunk); }
// cancellation
if (userNavigatesAway) conduit.cancel('navigation');

// ReadableStream consumer (Browser)
const conduit = client.streamConduit({ prompt });
const rs = conduit.toWebStream();
const reader = rs.getReader();
try { while(true) { const { done, value } = await reader.read(); if (done) break; renderChunk(value); } } finally { reader.releaseLock(); }

// Retry example using resume token
const conduit = client.streamConduit({ prompt }); let token = null;
for await (const chunk of conduit) { token = conduit.getResumeToken(); maybePersistToken(token); }
// later
const resumed = client.retryFrom(token); for await (const chunk of resumed) { ... }
